class ImageSwapper{Allow(e){e.preventDefault()}Drag(e){e.dataTransfer.setData("imageId",e.target.id)}Drop(e){e.preventDefault();let a=document.getElementById(e.dataTransfer.getData("imageId")),t=document.getElementById(e.target.id),r=a.src;a.src=t.src,t.src=r}}let imageSwapper=new ImageSwapper;